import os
import time
import osmnx as ox
import pandas as pd
import geopandas as gpd
import networkx as nx
import folium

ox.settings.use_cache = True
ox.settings.log_console = True
ox.settings.timeout = 300

graph_path = "/content/velachery_road_network.graphml"

if os.path.exists(graph_path):
    print("Loading saved Velachery road network...")
    G = ox.load_graphml(graph_path)
else:
    G = None
    last_error = None
    # Keep the first request reasonably small; retry transient Overpass 502/504 errors.
    for radius in (1000, 750):
        for attempt in range(1, 4):
            try:
                print(f"Requesting Velachery drive network: radius={radius}m, attempt={attempt}/3")
                G = ox.graph_from_address(
                    "Velachery, Chennai, Tamil Nadu, India",
                    dist=radius,
                    network_type="drive",
                    simplify=True
                )
                if G.number_of_nodes() == 0:
                    raise RuntimeError("OpenStreetMap returned an empty road graph.")
                ox.save_graphml(G, filepath=graph_path)
                print("Road network downloaded and cached for this Colab runtime.")
                break
            except Exception as exc:
                last_error = exc
                wait = 15 * (2 ** (attempt - 1))
                print(f"Download failed ({type(exc).__name__}): {exc}")
                if attempt < 3:
                    print(f"Retrying in {wait} seconds...")
                    time.sleep(wait)
        if G is not None:
            break
    if G is None:
        raise RuntimeError(
            "Overpass is currently overloaded. Wait and rerun this cell only. "
            "Do not rerun the full notebook."
        ) from last_error

nodes, edges = ox.graph_to_gdfs(G)
print("Road network ready!")
print("Nodes:", len(nodes))
print("Edges:", len(edges))

