# REWARD FUNCTION

def calculate_reward(
    old_distance,
    new_distance,
    reached_destination,
    flood_risk,
    invalid_action=False
):

    reward = 0

    # Destination reached
    if reached_destination:
        reward += 100

    # Invalid movement
    elif invalid_action:
        reward -= 20

    else:

        # Encourage progress
        if new_distance < old_distance:
            reward += 10

        # Penalize moving away
        elif new_distance > old_distance:
            reward -= 10

        # Penalize historical flood risk
        if flood_risk:
            reward -= 30

        # Small movement cost
        reward -= 1

    return reward

print("Successful evacuation:",
      calculate_reward(1000, 0, True, False))

print("Safe movement:",
      calculate_reward(1000, 800, False, False))

print("Flood-risk road:",
      calculate_reward(1000, 800, False, True))

print("Moving away:",
      calculate_reward(800, 1000, False, False))

print("Invalid action:",
      calculate_reward(1000, 1000, False, False, True))

